"use client";

import React, { createContext, useContext, useEffect, useState } from "react";

type Lang = "ar" | "en";
type Dir = "rtl" | "ltr";

interface LanguageContextProps {
  lang: Lang;
  dir: Dir;
  isRtl: boolean;
  toggleLanguage: (newLang?: Lang) => void;
  setLang: (newLang: Lang) => void;
}

const LanguageContext = createContext<LanguageContextProps | undefined>(undefined);

export const LanguageProvider = ({ children }: { children: React.ReactNode }) => {
  const [lang, setLangState] = useState<Lang>("ar");

  useEffect(() => {
    // On mount, read from localStorage
    const savedLang = localStorage.getItem("eagleon_lang") as Lang;
    if (savedLang === "ar" || savedLang === "en") {
      setLangState(savedLang);
      document.documentElement.lang = savedLang;
      document.documentElement.dir = savedLang === "ar" ? "rtl" : "ltr";
    } else {
      // Default to Arabic if no saved preference
      setLangState("ar");
      document.documentElement.lang = "ar";
      document.documentElement.dir = "rtl";
    }
  }, []);

  const setLang = (newLang: Lang) => {
    setLangState(newLang);
    localStorage.setItem("eagleon_lang", newLang);
    document.documentElement.lang = newLang;
    document.documentElement.dir = newLang === "ar" ? "rtl" : "ltr";
  };

  const toggleLanguage = (newLang?: Lang) => {
    if (newLang) {
      setLang(newLang);
    } else {
      setLang(lang === "ar" ? "en" : "ar");
    }
  };

  return (
    <LanguageContext.Provider value={{ lang, dir: lang === "ar" ? "rtl" : "ltr", isRtl: lang === "ar", toggleLanguage, setLang }}>
      {children}
    </LanguageContext.Provider>
  );
};

export const useLanguage = () => {
  const context = useContext(LanguageContext);
  if (!context) {
    throw new Error("useLanguage must be used within a LanguageProvider");
  }
  return context;
};
